    25→import java.util.Map;
    26→import java.util.Set;
    27→import java.util.concurrent.ConcurrentHashMap;
    28→
    29→/**
    30→ * http请求工具类
    31→ *
    32→ * @author kfzx-chenwh3
    33→ */
    34→public class HttpClientTools {
    35→    private static final Logger LOGGER = LoggerFactory.getLogger(HttpClientTools.class);
    36→    private static final String CLIENT_THREAD_POOL_NAME = "DubboHttpClientHandler";
    37→
    38→    private volatile boolean init = false;
    39→
    40→    private static HttpClientTools INSTANCE = new HttpClientTools();
    41→
    42→    private HttpClient client;
    43→    private HttpAsyncClient asyncClient;
    44→    private ExecutorRepository callBackExecutorRepository;
    45→
    46→    private String httpClientVersion;
    47→
    48→    private long lastRebuildAsyncClientTimeMills;
    49→
    50→    private volatile boolean rebuildHttpClient = false;
    51→
    52→    /**
    53→     * 存放 application.properties场景的 httpclient类型，使用并发map，免去手动加锁的操作
    54→     */
    55→    private static Map<String,Boolean> HTTP_CLIENT_VERSIONS = new ConcurrentHashMap<String, Boolean>(10);
    56→
    57→
    58→    private HttpClientTools() {
    59→    }
    60→
    61→    /**
    62→     * 确保仅初始化一次
    63→     */
    64→    public synchronized void init() {
    65→        if (this.init){
    66→            return;
    67→        }
    68→        this.init = true;
    69→        //是否在连接池异常场景重建HTTP连接池
    70→        final String rebuildHttpClientStr = Meta.getParamWithDefault("false","ENV_HTTP_CLIENT_REACTOR_REBUILD_ENABLE");
    71→        try {
    72→            rebuildHttpClient = Boolean.parseBoolean(rebuildHttpClientStr);
    73→        } catch (Exception ex) {
    74→            LOGGER.error("Parse ENV_HTTP_CLIENT_REACTOR_REBUILD_ENABLE value [{}] failed,will not rebuild http client when reactor",rebuildHttpClientStr);
    75→        }
    76→        // 初始化客户端
    77→        this.httpClientVersion = getHttpClientVersion();
    78→        LOGGER.info("Use Httpclient Version:{} and rebuild http client flag:{}" ,httpClientVersion,rebuildHttpClientStr);
    79→
    80→        // 初始化url
    81→        URL initUrl = initUrl(httpClientVersion);
    82→
    83→        // 初始化回调的executor
    84→        this.callBackExecutorRepository = ExtensionLoader.getExtensionLoader(ExecutorRepository.class).getDefaultExtension();
    85→        this.callBackExecutorRepository.createExecutorIfAbsent(initUrl);
    86→
    87→        // 初始httpclient
    88→        this.initClient(initUrl);
    89→        this.initAsyncClient(initUrl);
    90→    }
    91→
    92→    /**
    93→     * 初始化url
    94→     * @param httpClientVal
    95→     * @return
    96→     */
    97→    private URL initUrl(String httpClientVal) {
    98→        StringBuilder initUrlBuilder = new StringBuilder("dubbo://127.0.0.1:28080");
    99→        URL url = URL.valueOf(initUrlBuilder.toString());
   100→
   101→        Map<String,String> paramMap = new HashMap<String, String>(10);
   102→        paramMap.put(Constants.HTTP_CLIENT_KEY,httpClientVal);
   103→        paramMap.put(Constants.SIDE_KEY,Constants.CONSUMER_SIDE);
   104→        paramMap.put(Constants.THREAD_NAME_KEY,CLIENT_THREAD_POOL_NAME);
   105→        paramMap.put(Constants.THREADPOOL_KEY,Constants.DEFAULT_CLIENT_THREADPOOL);
   106→        return url.addParameters(paramMap);
   107→    }
   108→
   109→    /**
   110→     * 获取当前dubbo的protocol配置中的httpClient的版本
   111→     * @return
   112→     */
   113→    private String getHttpClientVersion() {
   114→        // 从缓存中获取
   115→        if (!CollectionUtils.isEmpty(HTTP_CLIENT_VERSIONS)) {
   116→            return HTTP_CLIENT_VERSIONS.keySet().iterator().next();
   117→        }
   118→
   119→        // 从protocolConfig实例中获取
   120→        Map<String, ProtocolConfig> protocolConfigMap = SpringExtensionFactory.getBeansOfType(ProtocolConfig.class);
   121→        for (String protocolId : protocolConfigMap.keySet()) {
   122→            ProtocolConfig config = protocolConfigMap.get(protocolId);
   123→            // 取 第一个 dubbo协议中配置的httpclient版本
   124→            if (config != null && Constants.DEFAULT_PROTOCOL.equalsIgnoreCase(config.getName())
   125→                    && StringUtils.isNotBlank(config.getHttpclient())) {
   126→                return StringUtils.trimToEmpty(config.getHttpclient());
   127→            }
   128→        }
   129→        return "";
   130→    }
   131→
   132→    public static void addHttpClientVersion(String type) {
   133→        if (StringUtils.isBlank(type)) {
   134→            return;
   135→        }
   136→        HTTP_CLIENT_VERSIONS.put(StringUtils.trimToEmpty(type), Boolean.TRUE);
   137→    }
   138→
   139→    private static HttpTransporter getTransporter() {
   140→        return (HttpTransporter) ExtensionLoader.getExtensionLoader(HttpTransporter.class).getAdaptiveExtension();
   141→    }
   142→
   143→    public static HttpClientTools getInstance() {
   144→        return INSTANCE;
   145→    }
   146→
   147→    private void initClient(URL url){
   148→        if (this.client != null){
   149→            return;
   150→        }
   151→        try {
   152→            this.client = getTransporter().init(url);
   153→        } catch (Throwable e) {
   154→            LOGGER.error("init client error.",e);
   155→            throw new RuntimeException(e);
   156→        }
   157→    }
   158→
   159→    private void initAsyncClient(URL url){
   160→        if (this.asyncClient != null) {
   161→            return;
   162→        }
   163→        try {
   164→            this.asyncClient = getTransporter().initAsync(url);
   165→        } catch (Throwable e) {
   166→            LOGGER.error("init async client error.",e);
   167→            throw new RuntimeException(e);
   168→        }
   169→    }
   170→
   171→    /**
   172→     * 异步调用（使用线程池）
   173→     * @param httpRequest
   174→     * @param callback
   175→     */
   176→    public void doHttpRequest(FullHttpRequest httpRequest, HttpFutureCallback callback) {
   177→        try {
   178→            this.asyncClient.execute(httpRequest,callback);
   179→        } catch (IllegalStateException ex) {
   180→            rebuildHttpClient(ex);
   181→            throw ex;
   182→        }
   183→        LOGGER.debug("HttpClient starts to send httpRequest:{}", httpRequest.toString());
   184→    }
   185→
   186→    private void rebuildHttpClient(IllegalStateException ex) {
   187→        //开关关闭或异常非线程池关闭的时不重建
   188→        if(!rebuildHttpClient || ex.getMessage() == null || !ex.getMessage().contains("I/O reactor status: STOPPED")) {
   189→            return;
   190→        }
   191→        //重新创建连接池
   192→        HttpAsyncClient newAsyncClient = createNewAsyncClientWhenReactorStop();
   193→        //替换原连接池并进行关闭处理
   194→        if(newAsyncClient != null) {
   195→            HttpAsyncClient oldAsyncClient = this.asyncClient;
   196→            this.asyncClient = newAsyncClient;
   197→            oldAsyncClient.stop();
   198→        }
   199→    }
   200→
   201→    /**
   202→     * 重新生成httpclient的异步连接池
   203→     * 1.使用锁的方式防止并发进入
   204→     * 2.策略采用15秒内不重新创建
   205→     * @return 异步连接池
   206→     */
   207→    private synchronized HttpAsyncClient createNewAsyncClientWhenReactorStop() {
   208→        HttpAsyncClient client = null;
   209→        if(System.currentTimeMillis() - lastRebuildAsyncClientTimeMills > 15000) {
   210→            LOGGER.info("reactor was stopped and will create new async client pool,lastRebuildAsyncClientTimeMills={}" , lastRebuildAsyncClientTimeMills);
   211→            try {
   212→                client = getTransporter().initAsync(initUrl(httpClientVersion));
   213→                lastRebuildAsyncClientTimeMills = System.currentTimeMillis();
   214→            } catch (Exception e) {
   215→                LOGGER.error("create new async client pool occur error.",e);
   216→            }
   217→        }
   218→        return client;
   219→    }
   220→
   221→    /**
   222→     * 设置域名最大连接数
   223→     * @param entities
   224→     */
   225→    public void setMaxPerRoute(Set<ZoneDomainEntity> entities,boolean isAsync) {
   226→        if (isAsync){
   227→            ((AbstractHttpClient)this.asyncClient).updateMaxPerRoute(entities);
   228→
   229→        }
   230→    }
   231→
   232→    /**
   233→     * 同步调用（不使用线程池）
   234→     * @param httpRequest
   235→     */
   236→    public FullHttpResponse doHttpRequest(FullHttpRequest httpRequest) throws IOException {
   237→        //http客户端未完成初始化时进行健康检查返回空，防止空指针异常
   238→        if(this.client == null) {
   239→            return null;
   240→        }
   241→        return this.client.execute(httpRequest);
   242→    }
   243→
   244→    public void stop() {
   245→        if(this.client != null) {
   246→            this.client.stop();
   247→        }
   248→        if(this.asyncClient != null) {
   249→            this.asyncClient.stop();
   250→        }
   251→        if(this.callBackExecutorRepository != null) {
   252→            this.callBackExecutorRepository.destroyAll();
   253→        }
   254→    }
   255→}

