     1→package com.icbc.cocoa.health.zone;
     2→
     3→import com.alibaba.dubbo.common.Constants;
     4→import com.alibaba.dubbo.common.utils.HttpClientTools;
     5→import com.alibaba.dubbo.remoting.transport.http.HttpClientConstant;
     6→import com.alibaba.dubbo.remoting.transport.http.ZoneHttpDomainType;
     7→import com.icbc.cocoa.health.zone.impl.AbstractZoneHealthCheck;
     8→import com.icbc.cocoa.zone.ZoneConstants;
     9→import io.netty.handler.codec.http.DefaultFullHttpRequest;
    10→import io.netty.handler.codec.http.FullHttpRequest;
    11→import io.netty.handler.codec.http.FullHttpResponse;
    12→import io.netty.handler.codec.http.HttpMethod;
    13→import io.netty.handler.codec.http.HttpResponseStatus;
    14→import io.netty.handler.codec.http.HttpVersion;
    15→import org.apache.commons.lang3.StringUtils;
    16→import org.slf4j.Logger;
    17→import org.slf4j.LoggerFactory;
    18→
    19→import java.io.UnsupportedEncodingException;
    20→import java.util.HashMap;
    21→import java.util.Map;
    22→import java.util.concurrent.locks.ReentrantLock;
    23→
    24→/**
    25→ * slb的心跳检查任务
    26→ */
    27→public final class SlbHeartBeatTask implements Runnable {
    28→    private static final Logger LOGGER = LoggerFactory.getLogger(SlbHeartBeatTask.class);
    29→
    30→    private static final String SLB_ZONE_HEALTH_KEY = "unit-health";
    31→    private static final String SLB_SERVER_REBOOT = "-1";
    32→    private static final String SLB_SERVER_ZONE_GOOD_HEALTH = "true";
    33→
    34→    private static final String PROVIDER_PHYSICAL_ZONE = "PROVIDER_PHYSICAL_ZONE";
    35→    private static final String HOST_HEALTH_STATUS = "HOST_HEALTH_STATUS";
    36→
    37→    /**
    38→     * 建立连接超时(毫秒)
    39→     */
    40→    private final static int SHORT_CONNECT_TIMEOUT = 500;
    41→
    42→    /**
    43→     * 响应超时(毫秒)
    44→     */
    45→    private final static int SHORT_RESPONSE_TIMEOUT = 500;
    46→
    47→    private final ConsumerSlbHealthManager slbHealthManager;
    48→
    49→    /**
    50→     * 当前的健康状态：true=健康，false=不健康
    51→     */
    52→    private boolean currentHealthStatus = true;
    53→
    54→    /**
    55→     * 被检查失败的连续次数
    56→     */
    57→    private int checkedFailCount = 0;
    58→
    59→    /**
    60→     * 被检查成功的连续次数
    61→     */
    62→    private int checkedSuccessCount = 0;
    63→
    64→
    65→    private ReentrantLock lock = new ReentrantLock(false);
    66→
    67→    /**
    68→     * 失败探活的次数
    69→     */
    70→    private final int failCycle = 3;
    71→
    72→    /**
    73→     * 成功探活的次数
    74→     */
    75→    private final int successCycle = 1;
    76→
    77→    /**
    78→     * 被检查的域名
    79→     */
    80→    private String hostName;
    81→
    82→    /**
    83→     * 被检查的端口
    84→     */
    85→    private String url;
    86→
    87→    private ZoneHttpDomainType domainType;
    88→
    89→
    90→    public SlbHeartBeatTask(ConsumerSlbHealthManager slbHealthManager, String hostName, ZoneHttpDomainType domainType) {
    91→        this.slbHealthManager = slbHealthManager;
    92→        this.hostName = StringUtils.trimToEmpty(hostName);
    93→        this.domainType = domainType;
    94→        this.url = new StringBuilder("http://").append(this.hostName).append(":").append(ZoneConstants.DEFAULT_SERVER_PORT).append(HttpClientConstant.ZONE_HEALTH_HTTP_PATH).toString();
    95→    }
    96→
    97→    public void run() {
    98→
    99→            // 如果是灾备域名，不探测，直接将健康状态置为true,因为在两地三中心架构下，灾备单元只有一个，即便不可用也没有退路
   100→            if (ZoneHttpDomainType.isBackup(domainType)) {
   101→                LOGGER.debug("[zone] Skip disaster host in heartbeat task: {}",hostName);
   102→            } else {
   103→                try {
   104→                    // 发起健康检查探测 并更新探测结果
   105→                    Map<String, String> nowHealthResultMap = this.requestHostHealth();
   106→                    LOGGER.debug("[zone] hostName:{}, hostHealth:{}, providerPhysicalZone:{}",this.hostName,
   107→                            nowHealthResultMap == null ? "null" : nowHealthResultMap.get(HOST_HEALTH_STATUS),
   108→                            nowHealthResultMap == null ? "null" : nowHealthResultMap.get(PROVIDER_PHYSICAL_ZONE));
   109→                    if (nowHealthResultMap == null) {
   110→                        // 跳过未知的探测结果
   111→                        return;
   112→                    }
   113→                    lock.lock();
   114→                    updateHostHealth(Boolean.valueOf(nowHealthResultMap.get(HOST_HEALTH_STATUS)));
   115→                    if (StringUtils.isNotBlank(nowHealthResultMap.get(PROVIDER_PHYSICAL_ZONE))) {
   116→                        updateProviderPhysicalZone(nowHealthResultMap.get(PROVIDER_PHYSICAL_ZONE));
   117→                    }
   118→                    lock.unlock();
   119→                } catch (Exception e) {
   120→                    LOGGER.debug("[zone] SlbHeartBeatTask.run() failed! host={}.",hostName,e);
   121→                } finally {
   122→                    try {
   123→                        lock.unlock();
   124→                    } catch (Throwable ignored) {
   125→                        // do nothing
   126→                    }
   127→                }
   128→            }
   129→    }
   130→
   131→    private void updateProviderPhysicalZone(String providerPhysicalZone) {
   132→        slbHealthManager.setProviderPhysicalZone(hostName, providerPhysicalZone, domainType);
   133→    }
   134→
   135→    /**
   136→     * 更新域名维度的健康检查结果
   137→     * @param nowHealthResult
   138→     */
   139→    private void updateHostHealth(Boolean nowHealthResult) {
   140→        if (currentHealthStatus) {
   141→            if (nowHealthResult) {
   142→                // 当前健康，本次探测结果也是健康
   143→                checkedFailCount = 0;
   144→            } else if (++checkedFailCount >= failCycle) {
   145→                // 当前健康，本次不健康，且不健康次数达到阈值（默认3次）
   146→                currentHealthStatus = false;
   147→                checkedFailCount = 0;
   148→                slbHealthManager.setHostHealth(this.hostName, currentHealthStatus, domainType);
   149→                logHostHealthStatusChanged(hostName, domainType, true, false);
   150→            }
   151→        } else {
   152→            if (!nowHealthResult) {
   153→                // 当前不健康，本次探测结果也是不健康
   154→                checkedSuccessCount = 0;
   155→            } else if (++checkedSuccessCount >= successCycle) {
   156→                // 当前不健康，本次探测结果是健康
   157→                currentHealthStatus = true;
   158→                checkedSuccessCount = 0;
   159→                slbHealthManager.setHostHealth(hostName, currentHealthStatus, domainType);
   160→                logHostHealthStatusChanged(hostName, domainType, false, true);
   161→            }
   162→        }
   163→    }
   164→
   165→    private void logHostHealthStatusChanged(String hostName, ZoneHttpDomainType domainType,
   166→                                            boolean lastStatus, boolean nowStatus) {
   167→        LOGGER.error("[zone] HTTP health check status changed. hostName = {}, domainType = {}, lastHealthStatus = {}, nowHealthStatus = {}",
   168→                hostName,domainType,lastStatus,nowStatus);
   169→    }
   170→
   171→    /**
   172→     * 获取健康检查的结果
   173→     * @return
   174→     */
   175→    private Map<String, String> requestHostHealth(){
   176→        try {
   177→            FullHttpRequest request = new DefaultFullHttpRequest(HttpVersion.HTTP_1_1, HttpMethod.GET,this.url);
   178→/*
   179→            request.headers().add(HttpHeaders.Names.CONNECTION,HttpHeaders.Values.CLOSE);
   180→*/
   181→            request.headers().add(Constants.CONNECT_TIMEOUT_KEY, SHORT_CONNECT_TIMEOUT);
   182→            request.headers().add(Constants.TIMEOUT_KEY, SHORT_RESPONSE_TIMEOUT);
   183→
   184→            // 发送http请求
   185→            FullHttpResponse httpResponse = HttpClientTools.getInstance().doHttpRequest(request);
   186→
   187→            Boolean isZoneHealth = isZoneHealth(httpResponse);
   188→            // 如果探活结果是null，直接返回null （SLB_SERVER_REBOOT场景）
   189→            if (isZoneHealth == null) {
   190→                return null;
   191→            }
   192→
   193→            Map<String, String> hostHealthMap = new HashMap<String, String>(2);
   194→            hostHealthMap.put(HOST_HEALTH_STATUS, isZoneHealth.toString());
   195→
   196→            // 探活结果不为空，继续读取提供方的物理单元号
   197→            String physicalZone = readProviderPhysicalZone(httpResponse);
   198→            if (StringUtils.isNoneBlank(physicalZone)) {
   199→                hostHealthMap.put(PROVIDER_PHYSICAL_ZONE, physicalZone);
   200→            }
   201→
   202→            return hostHealthMap;
   203→        } catch (Exception e) {
   204→            LOGGER.warn("[zone] requestHostHealth fail, url:{}",StringUtils.trimToEmpty(this.url),e);
   205→            //  TODO 比如 java.net.UnknownHostException: dsf-monitor-VZone.icbc: dsf-monitor-VZone.icbc
   206→            // TODO org.apache.hc.client5.http.ConnectTimeoutException:
   207→            //     后端slb后端所有节点下线，slb会将unit-health设置为false，再报http状态码503；  最后F5探测到slb不可用会隔离slb机器，报超时
   208→            // TODO 网络异常时视为 单元检测失败------ 异常类型需要再细分一下，区分是客户端异常、服务器端异常
   209→            Map<String, String> hostHealthMap = new HashMap<String, String>(2);
   210→            hostHealthMap.put(HOST_HEALTH_STATUS, Boolean.FALSE.toString());
   211→            return hostHealthMap;
   212→        }
   213→    }
   214→
   215→    private String readProviderPhysicalZone(FullHttpResponse response) {
   216→        return StringUtils.trimToEmpty(response.headers().get(AbstractZoneHealthCheck.DSF_PROVIDER_PHYSICAL_ZONE));
   217→    }
   218→
   219→    private Boolean isZoneHealth(FullHttpResponse response) {
   220→        //结果为空时跳过健康检查
   221→        if(response == null) {
   222→            LOGGER.warn("[zone] Zone health check will be ignored, because response is null by http client is null, check url = {}",url);
   223→            return null;
   224→        }
   225→        // http状态码不为200，视为健康检查失败
   226→        boolean successStatus = HttpResponseStatus.OK.code() == response.status().code();
   227→        if (!successStatus) {
   228→            LOGGER.warn("[zone] Zone health check is false, because zone SLB return HTTP code = [{}], check url = {}",response.status().code(),url);
   229→            return false;
   230→        }
   231→
   232→        // http header中 单元健康探活结果不为空且不为true，视为健康检查失败
   233→        String healthValue = StringUtils.trimToEmpty(response.headers().get(SLB_ZONE_HEALTH_KEY));
   234→
   235→        // slb处于重启阶段，视为健康检查无效，先做这个检查
   236→        boolean tryAgain = SLB_SERVER_REBOOT.equals(healthValue);
   237→        if (tryAgain){
   238→            LOGGER.warn("[zone] Zone health check will be ignored, because SLB is rebooting, return unit-health = [-1], check url = {}",url);
   239→            return null;
   240→        }
   241→
   242→        boolean goodHealth = StringUtils.isBlank(healthValue) || SLB_SERVER_ZONE_GOOD_HEALTH.equals(healthValue);
   243→        if(!goodHealth){
   244→            LOGGER.warn("[zone] Zone health check is false, because SLB return unit-health = [{}], check url = {}",healthValue,url);
   245→            return false;
   246→        }
   247→
   248→        // http header中 穿透式探活的结果不为空且不为true，视为健康检查失败
   249→        String innerHealthValue = response.headers().get(AbstractZoneHealthCheck.DSF_INNER_HEALTHCHECK_RESULT);
   250→        // 如果响应包的header中没有这个key，说明提供方没有启用应用内处理层的穿透式探活，这时认为结果是健康的；如果有这个key，解析其布尔值
   251→        boolean innerGoodHealth = StringUtils.isBlank(innerHealthValue)
